# -*- coding: utf-8 -*-
"""v9：由 **v8** 生成 —— 把确认后的 **AI 披露** 写进 `## Content Generated by AI`。

依据：用户 2026-10-12 确认（INDEX §213/§215）：
  * 模型串 = `DeepSeek, model deepseek-v4-flash`；
  * 用途除原有四项外，**还确认了三项**：① 文献检索/引用核对；② 从图表/文档提取数值；
    ③ **把材料交给外部 AI 审阅/评估** —— 第三项**旧文未写**，必须补上。

做法：定位 `## Content Generated by AI` 与随后的 `## References`，**只替换这两者之间的正文**；
其余一字不动；**LF**；报告哈希从磁盘算；往返自检可逐字节还原 v8。

产物：`docs/PAPER_DAC2027_EN_v9_20261012.md`、`docs/PAPER_DAC2027_EN_v9_PROVENANCE.md`、
      `work/runs/eda64-20261010/n5_stage3/V9_GENERATION_REPORT.json`
"""
from __future__ import annotations

import hashlib
import json
import pathlib
import sys
import time

sys.stdout.reconfigure(encoding="utf-8", errors="replace")
REPO = pathlib.Path(__file__).resolve().parents[2]
V8 = REPO / "docs/PAPER_DAC2027_EN_v8_20261012.md"
V9 = REPO / "docs/PAPER_DAC2027_EN_v9_20261012.md"
V9P = REPO / "docs/PAPER_DAC2027_EN_v9_PROVENANCE.md"
OUT = REPO / "work/runs/eda64-20261010/n5_stage3"

HEAD = "## Content Generated by AI\n\n"
TAIL = "\n## References"

NEW = """The authors used an LLM-based coding agent (**DeepSeek**, model `deepseek-v4-flash`) inside the
authors' own repository. Its assistance covered: drafting and restructuring the English prose of all
sections; literature search and citation checking (every retained reference's DOI was resolved
against Crossref); extracting numeric values from figures, tables and internal documents; writing,
debugging and running the analysis and batch-execution scripts; rendering the figures from frozen
numeric artifacts; and executing the finite-element campaigns reported here (pre-registered
protocols, append-only ledgers, per-point host and version records). Draft material was also
submitted to external LLM services for review and evaluation; those reviews were advisory only, and
none of their output was used as evidence or entered any reported result.

No LLM output was used as evidence. Every number in this paper was produced by the authors'
simulation and analysis pipeline and is traceable to an artifact (run directory, gate report, label
table or ledger entry); no number was accepted from the model's own recall, and no claim was accepted
without an artifact behind it. The agent could not and did not promote any model state: promotion and
release decisions remain with the human authors. The human authors reviewed and edited all text,
verified all numbers against their artifacts, and take full responsibility for the content, including
the negative results and the stated limitations. Routine language editing and knowledge retrieval
were also performed with LLM assistance.
"""


def main() -> int:
    v8 = V8.read_text(encoding="utf-8")
    v8_sha = hashlib.sha256(V8.read_bytes()).hexdigest()
    if "\r\n" in v8:
        raise SystemExit("[FAIL] v8 含 CRLF（预期纯 LF）")
    i = v8.find(HEAD)
    if i < 0 or v8.count(HEAD) != 1:
        raise SystemExit("[FAIL] AI 章节标题未唯一命中")
    j = v8.find(TAIL, i)
    if j < 0:
        raise SystemExit("[FAIL] 找不到 References 边界")
    old_body = v8[i + len(HEAD):j]
    if "DeepSeek Harness" not in old_body:
        raise SystemExit("[FAIL] 旧 AI 正文字样不符，拒绝替换")
    v9 = v8[:i + len(HEAD)] + NEW + v8[j:]

    # 守卫：三项新用途必须出现；旧串必须消失；其余内容不变
    for must in ("literature search and citation checking", "extracting numeric values",
                 "external LLM services for review"):
        if must not in v9:
            raise SystemExit("[FAIL] 新披露缺少必需项：%s" % must)
    if "DeepSeek Harness" in v9:
        raise SystemExit("[FAIL] 旧模型串仍在")
    if len(v9) <= len(v8):
        raise SystemExit("[FAIL] v9 未变长（新披露更长）")

    v9_bytes = v9.encode("utf-8")
    V9.write_bytes(v9_bytes)                       # 写字节 ⇒ LF

    disk = V9.read_text(encoding="utf-8")
    disk_bytes = V9.read_bytes()
    if b"\r\n" in disk_bytes:
        raise SystemExit("[FAIL] v9 出现 CRLF")
    k = disk.find(HEAD)
    m = disk.find(TAIL, k)
    back = disk[:k + len(HEAD)] + old_body + disk[m:]
    if back != v8:
        raise SystemExit("[FAIL] 往返校验失败：还原后与 v8 不一致")

    import re
    wc = lambda s: len(re.findall(r"[A-Za-z0-9][A-Za-z0-9'’\-\./%]*", s[:s.find(HEAD)]))
    w8, w9 = wc(v8), wc(disk)
    rep = {"kind": "dac2027_en_v9_generation", "generated": time.strftime("%Y-%m-%dT%H:%M:%S"),
           "source": V8.name, "source_sha256": v8_sha, "source_bytes": len(V8.read_bytes()),
           "change": "只替换 `## Content Generated by AI` 与 `## References` 之间的正文",
           "ai_model_string_confirmed": "DeepSeek, model deepseek-v4-flash",
           "ai_scope_added": ["literature search / citation checking",
                              "extracting numeric values from figures/tables/documents",
                              "submitting draft material to external LLM services for review (advisory only)"],
           "output": V9.name, "output_sha256": hashlib.sha256(disk_bytes).hexdigest(),
           "output_bytes": len(disk_bytes), "output_eol": "LF",
           "body_words_v8": w8, "body_words_v9": w9, "body_words_delta": w9 - w8,
           "roundtrip_restores_v8": True,
           "page_note": "AI 披露是**必设章节**，**不得为页数删减**；本次 +%d 词会加重页数压力。" % (w9 - w8)}
    if hashlib.sha256(V9.read_bytes()).hexdigest() != rep["output_sha256"]:
        raise SystemExit("[FAIL] 报告哈希与磁盘不一致")
    OUT.mkdir(parents=True, exist_ok=True)
    (OUT / "V9_GENERATION_REPORT.json").write_bytes(
        (json.dumps(rep, ensure_ascii=False, indent=2) + "\n").encode("utf-8"))

    V9P.write_bytes(f"""# v9 出处说明（DAC 2027 英文稿）

- 生成：{time.strftime("%Y-%m-%d")}；由 **v8**（`{V8.name}`，sha256 `{v8_sha[:24]}`，
  {len(V8.read_bytes())} B）**仅替换 `## Content Generated by AI` 章节正文**生成。
- 产物：`{V9.name}`（sha256 `{rep["output_sha256"][:24]}`，{rep["output_bytes"]} B，**LF**）。
- 正文词数：v8 **{w8}** → v9 **{w9}**（{w9 - w8:+d}）。
- **自检**：从磁盘回读；**把旧正文换回 ⇒ 逐字节还原 v8**（证明只动了这一节）。

## 依据（用户 2026-10-12 确认）

- 模型串 = **`DeepSeek, model deepseek-v4-flash`**；
- 用途：除原有四项（英文润色／脚本与探针／台账／稿件生成的脚本化替换）外，**还确认了三项**：
  ① **文献检索与引用核对**；② **从图表/文档提取数值**；
  ③ **把材料交给外部 AI 审阅/评估** —— 其中 ③ **旧文未写**，本版补上，并**明确写为"仅供参考、
  其输出未作为证据、未进入任何结果"**。

## 边界

- **不改任何数字、不改任何图表**；除 AI 章节外**一字未动**；
- AI 披露是**必设章节**，**不得为页数删减**（本次 +{w9 - w8} 词会加重页数压力）。

## 页数

DAC 限 **6 页 + 1 页仅参考文献**；本机**无 TeX**，**页数仍未编译验证**。

## 不主张

- **不主张** v9 满足 6 页；**不主张** v9 已可提交；不提升任何状态。
""".encode("utf-8"))

    print("v8 %d B（sha %s）→ v9 %d B（sha %s）" % (rep["source_bytes"], v8_sha[:16],
                                                  rep["output_bytes"], rep["output_sha256"][:16]))
    print("旧正文 %d 字符 → 新正文 %d 字符" % (len(old_body), len(NEW)))
    print("正文词数 v8 %d → v9 %d（%+d）" % (w8, w9, w9 - w8))
    print("自检：回读 + 往返还原 v8 通过；三项新用途齐备、旧串已消失、无 CRLF、哈希一致")
    print("写出:", V9.name, "|", V9P.name, "| V9_GENERATION_REPORT.json")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
